mapper.select:
SELECT CU.USER_NO, CU.USER_NM, CU.FIRM_NM, (SELECT TYPE_NAME FROM CBCI_BIZTYPE CB WHERE CB.TYPE_NO = CU.BUSINESS_TYPE) AS BUSINESS_TYPE, CU.REG_DATE, CU.USER_ID , CU.USER_NM AS REP_NM, CU.USER_PHONE , MUI.SEQ, MUI.REQUEST_STATUS , MUI.MONEYBANK_REQUEST_DATE , MUI.DIVISION , MUI.INTEREST_RATE, MUI.FEE_RATE, MUI.BUSINESS_PERIOD , MUI.SALES_AMOUNT , IFNULL(MUI.B2B_LIMIT_AMOUNT, 0) AS B2B_LIMIT_AMOUNT, MUI.REQ_LIMIT_AMOUNT , MUI.REQUEST_SHOP , MUI.WHOLESALE_MALL_NM, IFNULL(MUI.PERSON_CREDIT_SCORE, "-") AS PERSON_CREDIT_SCORE FROM MONEYBANK_USER_INFO MUI LEFT JOIN CBCI_USER CU ON CU.USER_NO = MUI.USER_NO
WHERE CU.USER_NM like #{REP_NM} AND CU.FIRM_NM like #{FIRM_NM}
AND MUI.DIVISION = #{DIVISION}
AND MUI.REQUEST_STATUS IN (${progressStatus})
AND CU.USER_NO = MUI.USER_NO
AND MUI.REQ_LIMIT_AMOUNT >= ${minAmount}*1000000 AND MUI.REQ_LIMIT_AMOUNT <= ${maxAmount}*1000000 AND MUI.MONEYBANK_REQUEST_DATE >= #{fromDate} AND MUI.MONEYBANK_REQUEST_DATE <= #{toDate}
ORDER BY MUI.MONEYBANK_REQUEST_DATE DESC
LIMIT 0, 10

SELECT FOUND_ROWS() AS TOTAL_COUNT, RESULT_TB.*
,COUNT(*) AS TOTAL_REQ ,SUM(RESULT_TB.B2B_LIMIT_AMOUNT) AS TOTAL_AMOUNTS ,ROUND(SUM(RESULT_TB.DAILY_USAGE_FEE)/COUNT(*), 3) AS USAGE_FEE_AVG ,SUM(RESULT_TB.REPAYMENT_REMAINING_AMOUNT) AS REMAINING_AVG
FROM(
SELECT MUI.SEQ, MUI.USER_NO, CU.USER_NM, CU.FIRM_NM, MUI.DIVISION, MUI.B2B_LIMIT_AMOUNT, "헬로페이 선지급" AS CURR_SERVICE, DATE_FORMAT(MUI.MONEYBANK_REQUEST_DATE, '%Y-%m-%d') AS MONEYBANK_REQUEST_DATE, DATE_FORMAT(MUI.APPROVAL_DATE, '%Y-%m-%d') AS APPROVAL_DATE, DATE_FORMAT(MUI.CONTRACT_DATE, '%Y-%m-%d') AS CONTRACT_DATE, DATE_FORMAT(MUI.CONTRACT_EXPIRE_DATE, '%Y-%m-%d') AS CONTRACT_EXPIRE_DATE, IFNULL((SELECT CCR.CRA_GRADE FROM CBCI_CRA_RESULT CCR WHERE CCR.USER_NO = MUI.USER_NO ORDER BY str_to_date(CCR.INPUT_DATE, '%Y-%m-%d %k:%i:%s') DESC LIMIT 1), "-") AS CRA_GRADE, IFNULL((SELECT daily_interest_fee FROM HELLOPAY_B2B_EXECUTE_INFO HBR WHERE HBR.SEQ = MUI.SEQ LIMIT 1), 0) AS DAILY_INTEREST_RATE, IFNULL((SELECT daily_usage_fee FROM HELLOPAY_B2B_EXECUTE_INFO HBR WHERE HBR.seq = MUI.SEQ LIMIT 1), 0) AS DAILY_USAGE_FEE, IFNULL(MUI.DEMAND_ACC_BANK_NM, "") AS DEMAND_ACC_BANK_NM, IFNULL(MUI.DEMAND_ACC_NUMBER, "-") AS DEMAND_ACC_NUMBER, IFNULL(MUI.MAIN_ACC_BANK_NM, "") AS MAIN_ACC_BANK_NM, IFNULL(MUI.MAIN_ACC_NUMBER, "-") AS MAIN_ACC_NUMBER, IFNULL((SELECT SUM(INNER_RESULT.REPAY_REMAIN_TTL) FROM ( SELECT INNER_HBR.seq AS SEQ, MIN(INNER_HBR.repayment_remaining_amount) AS REPAY_REMAIN_TTL FROM HELLOPAY_B2B_REPAYMENT INNER_HBR GROUP BY INNER_HBR.entry ) INNER_RESULT WHERE INNER_RESULT.SEQ = MUI.SEQ ), 0 ) AS REPAYMENT_REMAINING_AMOUNT FROM MONEYBANK_USER_INFO MUI LEFT JOIN CBCI_USER CU ON MUI.USER_NO = CU.USER_NO WHERE CU.USER_ID LIKE #{USER_ID} AND CU.USER_NM LIKE #{REP_NM} AND CU.FIRM_NM LIKE #{FIRM_NM}
AND MUI.CONTRACT_DATE >= #{fromDate}
AND MUI.CONTRACT_DATE <= #{toDate}
AND MUI.B2B_LIMIT_AMOUNT BETWEEN ${minAmount} AND ${maxAmount}
AND MUI.DIVISION = #{DIVISION}
AND HBRI.request_status != "00"
AND HBRI.request_status = "00"
ORDER BY ${ORDER_BY} )RESULT_TB
LIMIT ${LIMIT}
